<?php
namespace App\Http\Controllers\Mobile;
use App\Http\Controllers\Controller;use App\Models\AuditLog;use App\Models\User;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;use Illuminate\Validation\ValidationException;
class MobileAuthController extends Controller{
 public function store(Request $request):JsonResponse{$data=$request->validate(['email'=>['required','email'],'password'=>['required'],'device_name'=>['required','string','max:100']]);$user=User::where('email',mb_strtolower($data['email']))->first();if(!$user||!$user->is_active||!$user->account_claimed_at||!$user->hasVerifiedEmail()||$user->role->value!=='patient'||!Hash::check($data['password'],$user->password))throw ValidationException::withMessages(['email'=>['The provided credentials are incorrect.']]);$expires=now()->addDays(30);$token=$user->createToken($data['device_name'],['mobile:v1','profile:read','profile:update','appointments:self','messages:self','documents:self','consultations:self'],$expires);AuditLog::create(['actor_id'=>$user->id,'action'=>'identity.mobile_v1_token_created','subject_type'=>User::class,'subject_id'=>$user->id,'metadata'=>['device_name'=>$data['device_name']],'ip_address'=>$request->ip()]);return response()->json(['data'=>['access_token'=>$token->plainTextToken,'token_type'=>'Bearer','expires_at'=>$expires->toIso8601String(),'user'=>['id'=>$user->id,'name'=>$user->name,'email'=>$user->email]]]);}
 public function destroy(Request $request):JsonResponse{$request->user()->currentAccessToken()?->delete();return response()->json(['data'=>null,'message'=>'Signed out.']);}
}
